// 获取键盘输入字符 -----------------------------------------
u8 keyscan(u8 kps,u16 cdx,u16 cdy)
{
	char cn = 0;
	
	if((kps > 3)|| 							// 非法键盘
		 (kps == 0)) 							// 不显示键盘
	{
		return cn;
	}
	else
	{
		if((cur_tpx > 22)&&(cur_tpx < 112)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.00
		{
			switch(kps)
			{
				case 1: cn = '1'; break; 				// 数字键盘
				case 2: cn = 'q'; break; 				// 小写字母
				case 3: cn = 'Q'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 112)&&(cur_tpx < 202)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.01
		{
			switch(kps)
			{
				case 1: cn = '2'; break; 				// 数字键盘
				case 2: cn = 'w'; break; 				// 小写字母
				case 3: cn = 'W'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 202)&&(cur_tpx < 292)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.02
		{
			switch(kps)
			{
				case 1: cn = '3'; break; 				// 数字键盘
				case 2: cn = 'e'; break; 				// 小写字母
				case 3: cn = 'E'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 292)&&(cur_tpx < 382)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.03
		{
			switch(kps)
			{
				case 1: cn = '4'; break; 				// 数字键盘
				case 2: cn = 'r'; break; 				// 小写字母
				case 3: cn = 'R'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 382)&&(cur_tpx < 472)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.04
		{
			switch(kps)
			{
				case 1: cn = '5'; break; 				// 数字键盘
				case 2: cn = 't'; break; 				// 小写字母
				case 3: cn = 'T'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 472)&&(cur_tpx < 562)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.05
		{
			switch(kps)
			{
				case 1: cn = '6'; break; 				// 数字键盘
				case 2: cn = 'y'; break; 				// 小写字母
				case 3: cn = 'Y'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 562)&&(cur_tpx < 652)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.06
		{
			switch(kps)
			{
				case 1: cn = '7'; break; 				// 数字键盘
				case 2: cn = 'u'; break; 				// 小写字母
				case 3: cn = 'U'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 652)&&(cur_tpx < 742)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.07
		{
			switch(kps)
			{
				case 1: cn = '8'; break; 				// 数字键盘
				case 2: cn = 'i'; break; 				// 小写字母
				case 3: cn = 'I'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 742)&&(cur_tpx < 832)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.08
		{
			switch(kps)
			{
				case 1: cn = '9'; break; 				// 数字键盘
				case 2: cn = 'o'; break; 				// 小写字母
				case 3: cn = 'O'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 832)&&(cur_tpx < 922)&&(cur_tpy > 250)&&(cur_tpy < 335)) 			// 1.09
		{
			switch(kps)
			{
				case 1: cn = '0'; break; 				// 数字键盘
				case 2: cn = 'p'; break; 				// 小写字母
				case 3: cn = 'P'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 922)&&(cur_tpx < 1024)&&(cur_tpy > 250)&&(cur_tpy < 335)) 		// 1.10
		{
			cn = BACKSPACE_KEY;
		}
		else
		if((cur_tpx > 52)&&(cur_tpx < 142)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.00
		{
			switch(kps)
			{
				case 1: cn = '\''; break; 				// 数字键盘
				case 2: cn = 'a'; break; 				// 小写字母
				case 3: cn = 'A'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 142)&&(cur_tpx < 232)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.01
		{
			switch(kps)
			{
				case 1: cn = '|'; break; 				// 数字键盘
				case 2: cn = 's'; break; 				// 小写字母
				case 3: cn = 'S'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 232)&&(cur_tpx < 322)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.02
		{
			switch(kps)
			{
				case 1: cn = '{'; break; 				// 数字键盘
				case 2: cn = 'd'; break; 				// 小写字母
				case 3: cn = 'D'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 322)&&(cur_tpx < 412)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.03
		{
			switch(kps)
			{
				case 1: cn = '}'; break; 				// 数字键盘
				case 2: cn = 'f'; break; 				// 小写字母
				case 3: cn = 'F'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 412)&&(cur_tpx < 502)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.04
		{
			switch(kps)
			{
				case 1: cn = '%'; break; 				// 数字键盘
				case 2: cn = 'g'; break; 				// 小写字母
				case 3: cn = 'G'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 502)&&(cur_tpx < 592)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.05
		{
			switch(kps)
			{
				case 1: cn = '^'; break; 				// 数字键盘
				case 2: cn = 'h'; break; 				// 小写字母
				case 3: cn = 'H'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 592)&&(cur_tpx < 682)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.06
		{
			switch(kps)
			{
				case 1: cn = '*'; break; 				// 数字键盘
				case 2: cn = 'j'; break; 				// 小写字母
				case 3: cn = 'J'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 682)&&(cur_tpx < 772)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.07
		{
			switch(kps)
			{
				case 1: cn = '/'; break; 				// 数字键盘
				case 2: cn = 'k'; break; 				// 小写字母
				case 3: cn = 'K'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 772)&&(cur_tpx < 862)&&(cur_tpy > 335)&&(cur_tpy < 420)) 			// 2.08
		{
			switch(kps)
			{
				case 1: cn = '\"'; break; 			// 数字键盘
				case 2: cn = 'l'; break; 				// 小写字母
				case 3: cn = 'L'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 862)&&(cur_tpx < 1024)&&(cur_tpy > 335)&&(cur_tpy < 420)) 		// 2.09
		{
			cn = ENTER_KEY;
		}
		else
		if((cur_tpx > 22)&&(cur_tpx < 111)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.00
		{
			switch(kps)
			{
				case 1: return cn;  						// 数字键盘
				case 2: 												// 小写字母
				case 3: cn = SHIFT_KEY; break; 	// 大写字母
			}
		}
		else
		if((cur_tpx > 111)&&(cur_tpx < 200)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.01
		{
			switch(kps)
			{
				case 1: return cn;  						// 数字键盘
				case 2: cn = 'z'; break; 				// 小写字母
				case 3: cn = 'Z'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 200)&&(cur_tpx < 289)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.02
		{
			switch(kps)
			{
				case 1: return cn;  						// 数字键盘
				case 2: cn = 'x'; break; 				// 小写字母
				case 3: cn = 'X'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 289)&&(cur_tpx < 378)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.03
		{
			switch(kps)
			{
				case 1: cn = '$'; break; 				// 数字键盘
				case 2: cn = 'c'; break; 				// 小写字母
				case 3: cn = 'C'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 378)&&(cur_tpx < 467)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.04
		{
			switch(kps)
			{
				case 1: cn = '&'; break; 				// 数字键盘
				case 2: cn = 'v'; break; 				// 小写字母
				case 3: cn = 'V'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 467)&&(cur_tpx < 556)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.05
		{
			switch(kps)
			{
				case 1: cn = '~'; break; 				// 数字键盘
				case 2: cn = 'b'; break; 				// 小写字母
				case 3: cn = 'B'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 556)&&(cur_tpx < 645)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.06
		{
			switch(kps)
			{
				case 1: cn = '#'; break; 				// 数字键盘
				case 2: cn = 'n'; break; 				// 小写字母
				case 3: cn = 'N'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 645)&&(cur_tpx < 734)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.07
		{
			switch(kps)
			{
				case 1: cn = '='; break; 				// 数字键盘
				case 2: cn = 'm'; break; 				// 小写字母
				case 3: cn = 'M'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 734)&&(cur_tpx < 823)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.08
		{
			switch(kps)
			{
				case 1: cn = '+'; break; 				// 数字键盘
				case 2: 												// 小写字母
				case 3: cn = '@'; break; 				// 大写字母
			}
		}
		else
		if((cur_tpx > 823)&&(cur_tpx < 912)&&(cur_tpy > 420)&&(cur_tpy < 505)) 			// 3.09
		{
			cn = '.';
		}
		else
		if((cur_tpx > 912)&&(cur_tpx < 1024)&&(cur_tpy > 420)&&(cur_tpy < 505)) 		// 3.10
		{
			switch(kps)
			{
				case 1: cn = ','; break; 				// 数字键盘
				case 2: 												// 小写字母
				case 3: cn = SHIFT_KEY; break; 	// 大写字母
			}
		}
		else
		if((cur_tpx > 22)&&(cur_tpx < 112)&&(cur_tpy > 505)&&(cur_tpy < 590)) 			// 4.00
		{
			switch(kps)
			{
				case 1: cn = TOABC_KEY; break; 	// 数字键盘
				case 2:  												// 小写字母
				case 3: cn = TO123_KEY; break; 	// 大写字母
			}
		}
		else
		if((cur_tpx > 112)&&(cur_tpx < 290)&&(cur_tpy > 505)&&(cur_tpy < 590)) 			// 4.01
		{
			cn = CLEAR_KEY;
		}
		else
		if((cur_tpx > 290)&&(cur_tpx < 742)&&(cur_tpy > 505)&&(cur_tpy < 590)) 			// 4.02
		{
			cn = ' ';
		}
		else
		if((cur_tpx > 742)&&(cur_tpx < 832)&&(cur_tpy > 505)&&(cur_tpy < 590)) 			// 4.03
		{
			cn = '_';
		}
		else
		if((cur_tpx > 832)&&(cur_tpx < 922)&&(cur_tpy > 505)&&(cur_tpy < 590)) 			// 4.04
		{
			cn = '-';
			
		}
		
	}
	
	//if(SoundSw == 1)
		BEEPER_PlayTones(tones_1khz);
	
	return cn;
}

